// Basic BRD validation without external modules
const raw = $json.message?.content;
let brd;
try {
  brd = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  return [{ json: { ...$json, valid: false, errors: ['BRD JSON parse failed: ' + e.message], brd: null } }];
}

const errors = [];
if (brd?.type !== 'brd') errors.push('type must be brd');
if (!brd?.title) errors.push('title is required');
if (!brd?.executiveSummary) errors.push('executiveSummary is required');
if (!brd?.problemStatement) errors.push('problemStatement is required');
if (!Array.isArray(brd?.businessObjectives)) errors.push('businessObjectives must be array');
if (!Array.isArray(brd?.stakeholders)) errors.push('stakeholders must be array');
if (!brd?.scope) errors.push('scope is required');

// Non-crypto hash (FNV-1a)
const fnv1a = (input) => {
  const str = String(input ?? '');
  let hash = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = (hash * 0x01000193) >>> 0;
  }
  return ('0000000' + hash.toString(16)).slice(-8);
};

const valid = errors.length === 0;
const brdHash = fnv1a(JSON.stringify(brd));

return [{ json: { ...$json, valid, errors, brd, brdHash } }];

// Normalize Qdrant docs into deterministic candidate list with stable ids
const items = $input.all();

const normalizeId = (doc) => {
  const md = doc.metadata || {};
  const mdId = md.id || md.path || md.l4 || md.l3 || md.l2 || md.l1;
  if (mdId) return String(mdId);
  const firstLine = String(doc.pageContent || '').split('\n')[0].trim();
  if (firstLine) return firstLine;
  return String(doc.pageContent || '').slice(0, 80);
};

const candidates = items
  .map(i => i.json.document)
  .filter(Boolean)
  .map((d) => ({
    id: normalizeId(d),
    text: d.pageContent,
    metadata: d.metadata || {},
    score: typeof d.score === 'number' ? d.score : null,
  }));

candidates.sort((a,b) => {
  const sa = (a.score ?? -1);
  const sb = (b.score ?? -1);
  if (sb !== sa) return sb - sa;
  return String(a.id).localeCompare(String(b.id));
});

return [{ json: { ...$('Validate BRD').first().json, capabilityCandidates: candidates } }];

