const threshold = $('Run Config').first().json.capabilityRelevanceThreshold;
const candidates = $('Aggregate Capability Candidates').first().json.capabilityCandidates || [];

const selectionRaw = $json.message?.content;
let selection;
try { selection = typeof selectionRaw === 'string' ? JSON.parse(selectionRaw) : selectionRaw; }
catch (e) { selection = { selected: [] }; }

const picked = new Set();
const selected = [];
for (const s of (selection.selected || [])) {
  const idx = s?.index;
  if (typeof idx !== 'number') continue;
  if ((s.relevanceScore ?? 0) < threshold) continue;
  if (picked.has(idx)) continue;

  const c = candidates[idx];
  if (!c) continue;

  picked.add(idx);
  selected.push(c);
}

const capabilityContext = selected.map(s => s.text).join('\n\n');

return [{
  json: {
    ...$('Aggregate Capability Candidates').first().json,
    selectedCapabilities: selected,
    capabilityContext,
    capabilitySelection: selection
  }
}];

