// Validate Business Architecture without external modules
let model;
try { model = JSON.parse($json.message.content); }
catch (e) {
  return [{ json: { ...$json, valid: false, errors: ['Business arch parse failed: ' + e.message], businessArch: null } }];
}

const errors = [];
if (!model?.name) errors.push('name is required');
if (!model?.layer) errors.push('layer is required');
if (!Array.isArray(model?.elements)) errors.push('elements must be array');
if (!Array.isArray(model?.relationships)) errors.push('relationships must be array');

const elementIds = new Set((model.elements || []).map(e => e.id));
for (const rel of (model.relationships || [])) {
  if (!elementIds.has(rel.source)) errors.push(`Relationship source not found: ${rel.source}`);
  if (!elementIds.has(rel.target)) errors.push(`Relationship target not found: ${rel.target}`);
}

const fnv1a = (str) => {
  let hash = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = (hash * 0x01000193) >>> 0;
  }
  return ('0000000' + hash.toString(16)).slice(-8);
};

const valid = errors.length === 0;
const businessArchHash = fnv1a(JSON.stringify(model));

return [{ json: { ...$('Build Capability Context').first().json, valid, errors, businessArch: model, businessArchHash } }];

// Deterministic ArchiMate XML with type mapping
const projectSlug = $('Apply Classification + Slugify').first().json.projectSlug;
const model = $json.businessArch;

if (!model || !Array.isArray(model.elements) || !Array.isArray(model.relationships)) {
  throw new Error('Missing or invalid businessArch for XML conversion');
}

const escapeXml = (t) => String(t ?? '')
  .replace(/&/g,'&amp;')
  .replace(/</g,'&lt;')
  .replace(/>/g,'&gt;')
  .replace(/\"/g,'&quot;')
  .replace(/'/g,'&apos;');

const fnv1a = (str) => {
  const s = String(str ?? '');
  let hash = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    hash ^= s.charCodeAt(i);
    hash = (hash * 0x01000193) >>> 0;
  }
  return ('000000000000' + hash.toString(16)).slice(-12);
};

const stableId = (s) => fnv1a(String(s));

// ArchiMate Tool expects specific xsi:type values
const mapElementType = (t) => {
  const s = String(t || '').toLowerCase();
  if (s.includes('capability')) return 'Capability';
  if (s.includes('actor') || s.includes('user') || s.includes('person')) return 'BusinessActor';
  if (s.includes('service')) return 'ApplicationService';
  if (s.includes('interface') || s.includes('ui')) return 'ApplicationInterface';
  if (s.includes('data') || s.includes('repository') || s.includes('storage') || s.includes('db')) return 'DataObject';
  if (s.includes('process')) return 'BusinessProcess';
  if (s.includes('component') || s.includes('logic') || s.includes('ingestion') || s.includes('api')) return 'ApplicationComponent';
  // fallback
  return 'ApplicationComponent';
};

const mapRelType = (t) => {
  const s = String(t || '').toLowerCase();
  // Use ArchiMate relationship types supported by Archi tool
  if (s === 'uses' || s.includes('use')) return 'ServingRelationship';
  if (s.includes('integrat') || s.includes('flow')) return 'FlowRelationship';
  if (s.includes('access') || s.includes('read') || s.includes('write') || s.includes('store') || s.includes('calculate')) return 'AccessRelationship';
  if (s.includes('realiz')) return 'RealizationRelationship';
  if (s.includes('assign')) return 'AssignmentRelationship';
  if (s.includes('depend')) return 'InfluenceRelationship';
  return 'AssociationRelationship';
};

const elementXmlId = (el) => `e-${stableId(`${projectSlug}:business_arch:${el.id}`)}`;
const relXmlId = (rel) => `r-${stableId(`${projectSlug}:${rel.type}:${rel.source}->${rel.target}`)}`;

const elements = [...model.elements].sort((a,b) => String(a.id).localeCompare(String(b.id)));
const relationships = [...model.relationships].sort((a,b) => `${a.type}|${a.source}|${a.target}`.localeCompare(`${b.type}|${b.source}|${b.target}`));

const elementIdMap = {};
for (const el of elements) elementIdMap[el.id] = elementXmlId(el);

const modelId = `m-${stableId(`${projectSlug}:model`)}`;
const folderId = `f-${stableId(`${projectSlug}:folder:elements`)}`;
const relFolderId = `f-${stableId(`${projectSlug}:folder:relations`)}`;

let xml = `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n` +
  `<archimate:model xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:archimate=\"http://www.archimatetool.com/archimate\" name=\"${escapeXml(model.name || 'Model')}\" id=\"${modelId}\" version=\"5.0.0\">\n`;

xml += `  <folder name=\"Elements\" id=\"${folderId}\" type=\"elements\">\n`;
for (const el of elements) {
  const xsiType = mapElementType(el.type);
  xml += `    <element xsi:type=\"archimate:${xsiType}\" name=\"${escapeXml(el.name)}\" id=\"${elementIdMap[el.id]}\">\n`;
  if (el.description) xml += `      <documentation>${escapeXml(el.description)}</documentation>\n`;
  xml += `    </element>\n`;
}
xml += `  </folder>\n`;

let relCount = 0;
xml += `  <folder name=\"Relations\" id=\"${relFolderId}\" type=\"relations\">\n`;
for (const rel of relationships) {
  const sid = elementIdMap[rel.source];
  const tid = elementIdMap[rel.target];
  if (!sid || !tid) continue;
  const relType = mapRelType(rel.type);
  xml += `    <element xsi:type=\"archimate:${relType}\" id=\"${relXmlId(rel)}\" source=\"${sid}\" target=\"${tid}\"/>\n`;
  relCount++;
}
xml += `  </folder>\n</archimate:model>`;

return [{ json: { ...$json, archimateXml: xml, elementCount: elements.length, relationshipCount: relCount } }];

// Input is output of "Normalize BRD Rows" which returns { rows: [...] }
const rows = $json.rows || [];
const hasBrd = Array.isArray(rows) && rows.length > 0;

return hasBrd
  ? [{ json: { hasBrd: true, brdFromDb: rows[0].content } }]
  : [{ json: { hasBrd: false } }];

// Ensure we always output exactly one item with rows[]
const items = $input.all();
if (!items.length) return [{ json: { rows: [] } }];

// Postgres node returns one item per row. Normalize into rows array.
const rows = items.map(i => i.json);
return [{ json: { rows } }];

// Prefer in-flight businessArch, fallback to DB insert output (no businessArch)
if ($json.businessArch) return [{ json: $json }];
return [{ json: { ...$json, businessArch: $('Validate Business Architecture').first().json.businessArch } }];

