const errors = [];
if (model.layer !== 'Application') errors.push('layer must be Application');
if (!Array.isArray(model.elements)) errors.push('elements must be array');
if (!Array.isArray(model.relationships)) errors.push('relationships must be array');
if (!Array.isArray(model.crossLayerRelationships)) errors.push('crossLayerRelationships must be array');

const appIds = new Set((model.elements || []).map(e => e.id));
for (const rel of (model.relationships || [])) {
  if (!appIds.has(rel.source)) errors.push(`App relationship source not found: ${rel.source}`);
  if (!appIds.has(rel.target)) errors.push(`App relationship target not found: ${rel.target}`);
}

const businessArch = $('Validate Business Architecture').first().json.businessArch;
const bizIds = new Set((businessArch?.elements || []).map(e => e.id));
for (const rel of (model.crossLayerRelationships || [])) {
  if (!bizIds.has(rel.businessSourceId)) errors.push(`Cross-layer businessSourceId not found: ${rel.businessSourceId}`);
  if (!appIds.has(rel.applicationTargetId)) errors.push(`Cross-layer applicationTargetId not found: ${rel.applicationTargetId}`);
}

const fnv1a = (input) => {
  const s = String(input ?? '');
  let hash = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    hash ^= s.charCodeAt(i);
    hash = (hash * 0x01000193) >>> 0;
  }
  return ('0000000' + hash.toString(16)).slice(-8);
};

const valid = errors.length === 0;
const applicationArchHash = fnv1a(JSON.stringify(model));

return [{ json: { ...$('Validate Business Architecture').first().json, valid, errors, applicationArch: model, applicationArchHash } }];

const projectSlug = $('Apply Classification + Slugify').first().json.projectSlug;
const businessArch = $('Validate Business Architecture').first().json.businessArch;
const appArch = $json.applicationArch;

if (!businessArch || !Array.isArray(businessArch.elements) || !Array.isArray(businessArch.relationships)) throw new Error('Missing businessArch');
if (!appArch || !Array.isArray(appArch.elements) || !Array.isArray(appArch.relationships) || !Array.isArray(appArch.crossLayerRelationships)) throw new Error('Missing applicationArch');

const escapeXml = (t) => String(t ?? '')
  .replace(/&/g,'&amp;')
  .replace(/</g,'&lt;')
  .replace(/>/g,'&gt;')
  .replace(/\"/g,'&quot;')
  .replace(/'/g,'&apos;');

const fnv1a = (str) => {
  const s = String(str ?? '');
  let hash = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { hash ^= s.charCodeAt(i); hash = (hash * 0x01000193) >>> 0; }
  return ('000000000000' + hash.toString(16)).slice(-12);
};

const stableId = (s) => fnv1a(String(s));

const mapElementType = (t) => {
  const s = String(t || '').toLowerCase();
  if (s.includes('capability')) return 'Capability';
  if (s.includes('actor') || s.includes('user') || s.includes('person')) return 'BusinessActor';
  if (s.includes('businessservice') || s.includes('business service')) return 'BusinessService';
  if (s.includes('process')) return 'BusinessProcess';
  if (s.includes('service')) return 'ApplicationService';
  if (s.includes('interface') || s.includes('ui')) return 'ApplicationInterface';
  if (s.includes('data') || s.includes('repository') || s.includes('storage') || s.includes('db')) return 'DataObject';
  if (s.includes('component') || s.includes('api') || s.includes('integration') || s.includes('function')) return 'ApplicationComponent';
  return 'ApplicationComponent';
};

const mapRelType = (t) => {
  const s = String(t || '').toLowerCase();
  if (s.includes('realiz')) return 'RealizationRelationship';
  if (s.includes('serve') || s.includes('use')) return 'ServingRelationship';
  if (s.includes('access') || s.includes('read') || s.includes('write')) return 'AccessRelationship';
  if (s.includes('flow')) return 'FlowRelationship';
  return 'AssociationRelationship';
};

const bizElements = [...businessArch.elements].sort((a,b) => String(a.id).localeCompare(String(b.id)));
const appElements = [...appArch.elements].sort((a,b) => String(a.id).localeCompare(String(b.id)));

const bizMap = {};
for (const el of bizElements) bizMap[el.id] = `e-${stableId(`${projectSlug}:business_arch:${el.id}`)}`;
const appMap = {};
for (const el of appElements) appMap[el.id] = `e-${stableId(`${projectSlug}:application_arch:${el.id}`)}`;

const modelId = `m-${stableId(`${projectSlug}:model:biz-app`)}`;
const bizFolderId = `f-${stableId(`${projectSlug}:folder:business`)}`;
const appFolderId = `f-${stableId(`${projectSlug}:folder:application`)}`;
const relFolderId = `f-${stableId(`${projectSlug}:folder:relations`)}`;

let xml = `<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n` +
  `<archimate:model xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xmlns:archimate=\"http://www.archimatetool.com/archimate\" name=\"${escapeXml(appArch.name || businessArch.name || 'Architecture Model')}\" id=\"${modelId}\" version=\"5.0.0\">\n`;

xml += `  <folder name=\"Business\" id=\"${bizFolderId}\" type=\"elements\">\n`;
for (const el of bizElements) {
  const xsiType = mapElementType(el.type);
  xml += `    <element xsi:type=\"archimate:${xsiType}\" name=\"${escapeXml(el.name)}\" id=\"${bizMap[el.id]}\">\n`;
  if (el.description) xml += `      <documentation>${escapeXml(el.description)}</documentation>\n`;
  xml += `    </element>\n`;
}
xml += `  </folder>\n`;

xml += `  <folder name=\"Application\" id=\"${appFolderId}\" type=\"elements\">\n`;
for (const el of appElements) {
  const xsiType = mapElementType(el.type);
  xml += `    <element xsi:type=\"archimate:${xsiType}\" name=\"${escapeXml(el.name)}\" id=\"${appMap[el.id]}\">\n`;
  if (el.description) xml += `      <documentation>${escapeXml(el.description)}</documentation>\n`;
  xml += `    </element>\n`;
}
xml += `  </folder>\n`;

let relCount = 0;
xml += `  <folder name=\"Relations\" id=\"${relFolderId}\" type=\"relations\">\n`;
const addRel = (type, sid, tid, key) => { xml += `    <element xsi:type=\"archimate:${type}\" id=\"r-${stableId(key)}\" source=\"${sid}\" target=\"${tid}\"/>\n`; relCount++; };

for (const rel of (businessArch.relationships || [])) {
  const sid = bizMap[rel.source];
  const tid = bizMap[rel.target];
  if (!sid || !tid) continue;
  addRel(mapRelType(rel.type), sid, tid, `${projectSlug}:biz:${rel.type}:${rel.source}->${rel.target}`);
}
for (const rel of (appArch.relationships || [])) {
  const sid = appMap[rel.source];
  const tid = appMap[rel.target];
  if (!sid || !tid) continue;
  addRel(mapRelType(rel.type), sid, tid, `${projectSlug}:app:${rel.type}:${rel.source}->${rel.target}`);
}
for (const rel of (appArch.crossLayerRelationships || [])) {
  const sid = bizMap[rel.businessSourceId];
  const tid = appMap[rel.applicationTargetId];
  if (!sid || !tid) continue;
  addRel(mapRelType(rel.type), sid, tid, `${projectSlug}:cross:${rel.type}:${rel.businessSourceId}->${rel.applicationTargetId}`);
}

xml += `  </folder>\n</archimate:model>`;

return [{ json: { ...$json, archimateXml: xml, elementCount: bizElements.length + appElements.length, relationshipCount: relCount } }];

const fnv1a = (input) => {
  const s = String(input ?? '');
  let hash = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    hash ^= s.charCodeAt(i);
    hash = (hash * 0x01000193) >>> 0;
  }
  return ('0000000' + hash.toString(16)).slice(-8);
};
return [{ json: { ...$json, archimateXmlHash: fnv1a($json.archimateXml) } }];
